INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('skin-peeler','Skin-Peeler','minion','legitch, abacba',NULL,'','SCP Fragmented Veil','{"slug":"skin-peeler","name":"Skin-Peeler","team":"minion","ability":"Once per game, at night, you may choose to become the Demon & have deaths be arbitrary until tomorrow (you have some control).","creator":"legitch, abacba","appearsIn":"SCP Fragmented Veil","lede":"The Skin-Peeler (SCP-3114) is an animated skeleton that drapes the living with the skin of the dead - controlling life and death.","summaryBullets":["The Skin-Peeler has the ability to activate a corpse party, controlling death itself for a full night & day whilst they become the Demon.","Deaths being arbitrary extends to during the day, where it can affect executions or other day deaths {{i|(like Slayer or Witch)}}, and the next night before the Skin-Peeler would normally wake {{i|(albeit doesn''t)}}.","Typically, when the Skin-Peeler activates a corpse party, either them or the Demon will die before it ends, as there would otherwise be 2 Demons."],"howToRun":["Each night, if the Skin-Peeler {{i|(or now the Demon)}} is marked with the **CORPSE PARTY** reminder, deaths are no longer arbitrary - remove it. Otherwise, wake the Skin-Peeler. They either shake their head no or yes. Put the Skin-Peeler to sleep.","If the Skin-Peeler shook their head yes, **they become the Demon & deaths until the Skin-Peeler would next wake are arbitrary** - show them the **YOU ARE** info token, then the Demon token, then mark them with the **CORPSE PARTY** and **WAS SKIN-PEELER** reminder. You may choose any players to kill or to protect throughout the rest of the night, upcoming day, and first half of the upcoming night to balance the game. Additional deaths are considered attacks from the Skin-Peeler.","If the Skin-Peeler changes characters for whatever reason, also mark them with the **WAS SKIN-PEELER** reminder."],"tips":["Let the Skin-Peeler communicate with you on who they want to live, and who they want to die during their corpse party. It''s generally a good idea to let them redirect any deaths from a player they know will die to another player, change the outcomes of Townsfolk abilities causing death, and protect evil players from execution, or either of the 2 standing Demons from death by execution. If any evil player however wants to net any extra kills during the Corpse Party, they must do it at the cost of a sacrifice of some kind. However, Storyteller discretion is advised on knowing when you should oblige by this, or not."],"quote":"You can''t save your skin, but I can!","iconBy":"le_nuberto","customBoxes":[{"title":"In the almanac JSON","content":"**Reminders:** Corpse party, Was Skin-Peeler"},{"title":"Alternative JSON","content":"If you apply the older secondary ability of the Skin-Peeler back to them, use this JSON.\n\nOn the script, place a mark on characters you want to have keep their ability on death. When they die for whatever reason, mark them with the **HAS ABILITY** reminder.\n\n**Skin-Peeler █+** (Minion)\nDead marked characters retain their ability, even if you change characters. At night, you may choose to become the Demon & have deaths be arbitrary until tomorrow.\n\n**First night:** If the Skin-Peeler has not yet used their ability: The Skin-Peeler either shows the ''no'' head signal, or the ''yes'' head signal.\n**Other nights:** If the Skin-Peeler used their ability yesterday, deaths are no longer arbitrary. If the Skin-Peeler has not yet used their ability: The Skin-Peeler either shows the ''no'' head signal, or the ''yes'' head signal.\n**Reminders:** Corpse party, Has ability, Has ability, Has ability, Was Skin-Peeler\n**Setup:** yes\n**Credit:** Ability: @legitch & @abacba. Image: @le_nuberto"}],"firstNight":30.3114,"otherNight":17.3114,"reminders":["Corpse party"],"remindersGlobal":["Was Skin-Peeler"],"setup":true,"firstNightReminder":"If the Skin-Peeler has not yet used their ability: The Skin-Peeler either shows the ''no'' head signal, or the ''yes'' head signal.","otherNightReminder":"If the Skin-Peeler used their ability yesterday, deaths are no longer arbitrary. If the Skin-Peeler has not yet used their ability: The Skin-Peeler either shows the ''no'' head signal, or the ''yes'' head signal.","art":"art/skin-peeler.png","jsonId":"skinpeeler_scp_fragmented_veil","curata":false}','scp-fragmented-veil/skin-peeler','published',datetime('now'),datetime('now')),
('horseman','Horseman!','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"horseman","name":"Horseman!","team":"minion","ability":"Each night*, a player lays dead if you guess who has your head. They know this dread, & their madness might turn true instead!","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Horseman searches for their head cried lost. A good player satchels it, but bears it''s curses'' cost.","summaryBullets":["1 good player will know they bear the head''s mark. They may risk turning fearful falsehoods into truths, or keep their mouth parked.","Anything is possible; monsters, demons, insanity! There may be no trace on what has happened - oh the inhumanity!","An amendment of fate can occur regardless of who knows the facts. As long as what''s said God knows to be false, it''s possible to react.","The headbearer should be judicious however; wintry neck hold still. For the Horseman pursues for their head by resolve and will.","The Horseman will take a turn to guess said wicked thief at night. A player of ut-most modesty will die if they''re right.","Typically, as of note, a correct guess should hurt greatly. Take the influential or cowardly, and bury them gravely."],"howToRun":["While preparing the first night, decide who will learn fright. Mark a good player with the **DREADED** reminder on sight.","Wake that player, show them the Horseman''s token {{i|(oh what fear they must feel from the nightmare to which they''ve awoken.)}}","Put them to sleep, they''ve experienced true terror - they acknowledge that they are the Horseman''s head bearer!","At any time {{i|(even at night)}}, if they something aligned false, you may choose to cast any action to make it honest of your own waltz.","Poisoning, killing, swaps, mis-registration; anything is possible, so no hesitation.","However the result is, it must make a reality against wrongs - you may use the **HAUNTING**, **DAUNTING**, and **JAUNTING** reminders as they belong.","Each night except the first, wake the Horseman. They point at any player, then put them to sleep as ran.","If they chose their head-taker {{i|(the one marked **DREADED**)}}, choose any player to die - mark them **BEHEADED**."],"tips":["Assess the situation of twisting reality by your whim. Act as though you have the power of a single Minion, or the good team may not be able to win!","**Optional rule:** A Horseman that is constantly rhyming is safe from everything. Though it reveals their presence public, their wrath remains permanently thrilling."],"quote":"Ichabod Crane, you old curr! Thought you could escape my wrath without deter? My sword breathes a deadly sheen, as it edges for your neck on this Halloween. I cast my curse and throw my eyes, yet you bite your thumb at me in surprise? Does nursery cries and limericks not mellow, or has misery acquaint you with strange bedfellows? Avast ye belayment, I''ve grown a-bore - cry ''Havoc!''; let slip the dogs of war! You protest my presence, and yet here I stand. ''You repent your sins just now?'', what a man! Be still by plea, I''ve seen worse: a pound of flesh for gold, and a kingdom for a horse.","iconBy":"harryandco","customBoxes":[{"title":"Credit","content":"Ability spawned o'' bewitch: The creator of swag, @legitch. Art of sorrows and woe: starlight travellers @harryandco."},{"title":"Alternative JSON","content":"For if you''re a killjoy, use this JSON.\n\n**Horseman! █~** (Minion)\n1 player knows their madness might become true. Each night*, guess which player it is: if correct, a player dies.\n\n**First night:** Wake a good player. Show them the Horseman''s character token.\n**Other nights:** The Horseman points to a player. If correct, a player dies.\n**Reminders:** Dead, Headholder, Haunting, Daunting, Jaunting\n**Credit:** Ability: @legitch. Art: @harryandco."}],"firstNight":28.6667,"otherNight":53.66611,"reminders":["Dreaded","Beheaded","Haunting","Daunting","Jaunting"],"setup":false,"firstNightReminder":"Wake a good player - up from bed! Show them the Horseman''s character token (they have their head!)","otherNightReminder":"The Horseman points to a player, scouring where their head lies. If correct, a player that can encounter death tonight dies!","art":"art/horseman.png","jsonId":"horseman_scp_fragmented_veil","curata":false}','scp-fragmented-veil/horseman','published',datetime('now'),datetime('now')),
('shadoo','Shadoo','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"shadoo","name":"Shadoo","team":"demon","ability":"Each night, see the Grimoire & choose a player: the next good player they choose dies at night*.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-017 is a humanoid of darkness incarnate, and walks in the shadows of others to perform their killings.","summaryBullets":["Each night, the Shadoo chooses a player to lurk in their shadow, and the next time they choose a good player either with their ability or by nomination, they''ll die when the Shadoo next wakes.","The Shadoo additionally sees the Grimoire when they wake, having omniscient knowledge of the game state.","The Shadoo can choose anyone with their ability - good players, other evil players, themselves, and even Travellers.","Players chosen by the Shadoo will have their next chosen good player die, even if it''s not in-between the time they were chosen and the next-time the Shadoo wakes at night.","Only good players can die to the Shadoo, even if a good player chosen then turns evil before they can die."],"howToRun":["Each night, all players marked with the **DARKENED** reminder token {{i|die}} - replace each affected players'' **DARKENED** reminder token with the **DEAD** reminder, then wake the Shadoo. Show them the Grimoire for as long as they need, then they point at any player. Mark that player with the **SHROUDED** reminder token. Put the Shadoo to sleep.","When a player with the **SHROUDED** reminder token nominates or chooses a good player with their ability, mark that player with the **DARKENED** reminder token and remove the **SHROUDED** reminder token from the previous one. If a player is marked with the **DARKENED** reminder token after the Shadoo woke but before they did in the same night, they {{i|die}} unless it''s the first night - replace their **DARKENED** reminder token with the **DEAD** reminder."],"iconBy":"le_nuberto","jinxes":[{"name":"Snake Charmer","align":"good","text":"Only 1 jinxed character can be in play.","id":"snakecharmer"},{"name":"Damsel","align":"good","text":"If the Shadoo is (or has been) in play, the Damsel is poisoned.","id":"damsel"},{"name":"Heretic","align":"good","text":"Only 1 jinxed character can be in play.","id":"heretic"},{"name":"Magician","align":"good","text":"When the Shadoo sees the Grimoire, the Minions'' and Magician''s character tokens are removed.","id":"magician"},{"name":"Poppy Grower","align":"good","text":"If the Poppy Grower is in play, the Shadoo does not see the Grimoire until the Poppy Grower dies.","id":"poppygrower"},{"name":"Visionary","align":"evil","text":"Only 1 jinxed character can be in play.","id":"visionary_the_bootleggers_anthology"},{"name":"Ornithologist","align":"good","text":"If the Ornithologist is in play, the Shadoo does not see the Grimoire until they die.","id":"ornithologist_2tfafullcharacterlist"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Ability:** Each night, see the Grimoire & choose a player: the next good player they choose by ability or nomination dies at night*.\n**Reminders:** Shrouded, Shrouded, Shrouded, Darkened, Darkened, Darkened, Dead"},{"title":"Alternative JSON & How to Run (Older)","content":"Use this JSON if you want to use the older version of this character with a built-in misregistration safe mechanism, at the cost of less reliable and swingy kills.\n\nEach night, all players marked with the DARKENED reminder token die - replace each affected players'' DARKENED reminder token with the DEAD reminder, then wake the Shadoo. Show them the Grimoire for as long as they need, then they point at any player. Mark that player with the SHROUDED reminder token. Put the Shadoo to sleep.\n\nWhen a player with the SHROUDED reminder token nominates or chooses a non-Demon player with their ability, mark that player with the DARKENED reminder token and remove the SHROUDED reminder token from the previous one. If a player is marked with the DARKENED reminder token after the Shadoo woke but before they did in the same night, they die unless it''s the first night - replace their DARKENED reminder token with the DEAD reminder.\n\nEach time the Shadoo is targeted by an ability that detects or affects good characters, if at-least one Minion is alive, choose what character and alignment the Shadoo registers as. Do whatever is appropriate, such as showing a good character token, nodding, giving finger signals, or allowing an ability to work that would normally only affect good, Townsfolk, or Outsider players.\n\n**Shadoo █~** (Demon)\nEach night, see the Grimoire & choose a player: the next non-Demon they choose dies at night*. You might register as good & a good character if a Minion lives.\n\n**First night:** Show the Grimoire to the Shadoo for as long as they need, they point to a player. The next good player that player chooses with their ability or nominates dies when they next wake.\n**Other nights:** Those marked to die, die. Show the Grimoire to the Shadoo for as long as they need, they point to a player. The next good player that player chooses with their ability or nominates dies when they next wake.\n**Reminders:** Shrouded, Shrouded, Shrouded, Darkened, Darkened, Darkened, Dead\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nSnake Charmer: Only 1 jinxed character can be in play.\nDamsel: If the Shadoo is (or has been) in play, the Damsel is poisoned.\nHeretic: Only 1 jinxed character can be in play.\nMagician: When the Shadoo sees the Grimoire, the Minions'' and Magician''s character tokens are removed.\nOgre: The Shadoo registers as evil to the Ogre.\nPoppy Grower: If the Poppy Grower is in play, the Shadoo does not see the Grimoire until the Poppy Grower dies.\nVisionary: Only 1 jinxed character can be in play.\nOrnithologist: If the Ornithologist is in play, the Shadoo does not see the Grimoire until they die."}],"firstNight":0.017,"otherNight":46.017,"reminders":["Shrouded","Shrouded","Shrouded","Shrouded","Shrouded","Darkened","Darkened","Darkened","Darkened","Darkened","Dead"],"setup":false,"special":[{"name":"grimoire","type":"signal","time":"night"}],"firstNightReminder":"Show the Grimoire to the Shadoo for as long as they need, they point to a player. The next good player that player chooses with their ability or nominates dies when they next wake.","otherNightReminder":"Those marked to die, die. Show the Grimoire to the Shadoo for as long as they need, they point to a player. The next good player that player chooses with their ability or nominates dies when they next wake.","art":"art/shadoo.png","jsonId":"shadoo_scp_fragmented_veil","curata":false}','scp-fragmented-veil/shadoo','published',datetime('now'),datetime('now'));
